<script setup lang="ts">
import {supplementLabels,supplementValue} from '../../domain/supplement';
import AppIcon from '../../components/AppIcon.vue';
import {ref} from 'vue';
import {onLoad,onShow} from '@dcloudio/uni-app';
import ActionButton from '../../components/ActionButton.vue';
import {request,loadSession,session,serverReady,signIn,signOut,errorMessage} from '../../services/api';
import {openMenu,notify,copyText} from '../../adapters/platform';
const tab=ref('profile'),loading=ref(true),error=ref(''),name=ref(''),saving=ref(false),working=ref(''),notes=ref<Record<string,string>>({});
const contributions=ref<any>({places:[],reviews:[]}),queue=ref<any>({places:[],reviews:[],reports:[],history:[]});
const actionLabels:Record<string,string>={supplement:'补充信息',confirm:'到访核对',submit:'提交地点',seed:'导入公开线索',approve:'审核通过',reject:'退回补充',restore:'恢复展示',hide:'隐藏地点',report:'地点纠错',seat:'更新空位',review:'提交体验',resolve:'处理纠错',resubmit:'修改投稿'};
const statusLabels:Record<string,string>={candidate:'真实地点 · 待核实',pending:'待审核',published:'已收录',rejected:'已退回',hidden:'已隐藏',approved:'已公开'};
onLoad(o=>{if(o?.tab)tab.value=String(o.tab);});
onShow(async()=>{loading.value=true;error.value='';await loadSession();name.value=session.value?.displayName||'';await refresh();loading.value=false;});
function back(){uni.reLaunch({url:'/pages/index/index'});}
async function refresh(){if(!session.value)return;try{contributions.value=await request('contributions');if(session.value.canReview)queue.value=await request('review-queue');}catch(e){error.value=errorMessage(e);}}
async function importCandidates(){if(working.value)return;working.value='import';error.value='';try{const r=await request('seed-candidates','POST',{});await refresh();notify('已导入 '+r.inserted+' 条官方公开线索，等待审核');}catch(e){error.value=errorMessage(e);}finally{working.value='';}}
async function saveProfile(){saving.value=true;error.value='';try{await request('me','PUT',{displayName:name.value});await loadSession();notify('贡献署名已保存');}catch(e){error.value=errorMessage(e);}finally{saving.value=false;}}
function contribute(id?:string){uni.navigateTo({url:'/pages/contribute/index'+(id?'?id='+encodeURIComponent(id):'')});}
function open(id:string){uni.navigateTo({url:'/pages/index/index?id='+id});}
async function review(kind:string,id:string,action:string,override?:string){if(working.value)return;const note=override?.trim()||notes.value[id]?.trim()||(action==='approve'?'已核对来源及收录条件':'');if(!note){error.value='请填写处理依据，方便贡献者理解与后续追溯。';return;}working.value=id;error.value='';try{await request('review/'+kind+'/'+id,'POST',{action,note});await refresh();notify('处理结果已保存到云端');}catch(e){error.value=errorMessage(e);}finally{working.value='';}}
async function copyId(){if(session.value){await copyText(session.value.userId);notify('已复制账号标识');}}
</script>
<template><view class="shell account-shell"><view class="topbar"><ActionButton class="brand" @click="back"><image class="brand-mark" src="/static/brand/logo-icon.png"/><view class="brand-words"><text>流动工位</text><text class="brand-sub">FlowSeat</text></view></ActionButton><ActionButton class="text-button" @click="back">返回探索</ActionButton></view>
<view class="account-heading"><view><view class="small-tag">Your work, your way.</view><view class="workspace-title">{{session?.displayName?'你好，'+session.displayName:'把好工位，留给下一位。'}}</view></view><ActionButton class="black-button" @click="contribute()">推荐地点 ＋</ActionButton></view>
<view v-if="loading" class="notice">正在读取云端记录…</view><view v-if="error" class="error-box" role="alert">{{error}}</view>
<view v-if="!loading&&!session" class="account-login"><view class="section-title">登录，开始共创。</view><view class="description">真实地点的收藏、投稿与体验将保存到云端。<text class="line-break"> </text>当前托管预览使用 ChatGPT 登录，未接入微信或手机号。</view><ActionButton class="black-button" :disabled="!serverReady" @click="signIn">使用 ChatGPT 登录</ActionButton><view v-if="!serverReady" class="error-box">服务未连接，暂时无法登录。请稍后重试。</view></view>
<template v-if="session"><view class="account-tabs"><ActionButton :class="{active:tab==='profile'}" @click="tab='profile'">账号与署名</ActionButton><ActionButton :class="{active:tab==='contributions'}" @click="tab='contributions'">我的贡献 <text>{{contributions.places.length+contributions.reviews.length}}</text></ActionButton><ActionButton v-if="session.canReview" :class="{active:tab==='review'}" @click="tab='review'">快速审核 <text>{{queue.places.length+queue.reviews.length+queue.reports.length}}</text></ActionButton></view>
<view v-if="tab==='profile'" class="profile-layout"><view class="profile-settings"><view class="section-title">你希望如何署名？</view><view class="description">署名会出现在公开地点和体验旁，不公开你的登录邮箱。</view><view class="field-label">贡献署名（2–24 字）</view><input v-model="name" class="form-input" maxlength="24" placeholder="你的名字或昵称"/><ActionButton class="black-button" :disabled="saving" @click="saveProfile">{{saving?'正在保存…':'保存贡献署名'}}</ActionButton><view class="account-id"><view class="field-label">账号标识</view><text>{{session.userId}}</text><ActionButton class="underlink" @click="copyId">复制</ActionButton></view><ActionButton class="text-button" @click="signOut">退出当前账号</ActionButton></view><view class="account-note"><text class="status-chip tone-free">{{session.canReview?'审核员账号':'社区贡献者'}}</text><view class="section-title">一处好工位，<text class="line-break"> </text>一份真实的经验。</view><view class="description">收藏真实地点会同步到云端。示例地点的收藏与测试体验仍只保存在本机。<text class="line-break"> </text><text class="line-break"> </text>投稿先审核，再公开；你可以在贡献记录中查看进度和处理依据。</view></view></view>
<view v-if="tab==='contributions'" class="contribution-list"><view v-if="!contributions.places.length&&!contributions.reviews.length" class="empty"><view class="empty-symbol">＋</view><view>你的第一份贡献，从一个好地方开始。</view><ActionButton class="outline-button" @click="contribute()">推荐地点</ActionButton></view><view v-for="p in contributions.places" :key="p.id" class="contribution-card"><view class="row"><view><view class="card-name">{{p.payload.name}}</view><view class="meta">{{p.payload.district}} · {{p.payload.type}} · {{new Date(p.created_at).toLocaleDateString()}}</view></view><text class="status-chip" :class="p.status==='published'?'tone-free':p.status==='pending'?'tone-unknown':'tone-paid'">{{statusLabels[p.status]}}</text></view><view v-if="p.note" class="notice">处理说明：{{p.note}}</view><view class="chips"><ActionButton v-if="['pending','rejected'].includes(p.status)" class="text-button" @click="contribute(p.id)">修改投稿</ActionButton><ActionButton v-if="p.status==='published'" class="text-button" @click="open(p.id)">查看地点</ActionButton></view></view><view v-for="r in contributions.reviews" :key="r.id" class="contribution-card"><view class="row"><view class="card-name">{{r.placeName}} · 办公体验</view><text class="status-chip tone-unknown">{{statusLabels[r.status]}}</text></view><view v-if="r.payload.kind==='supplement'" class="notice"><view>补充 {{supplementLabels[r.payload.field]}}：{{supplementValue(r.payload.previous)}} → {{supplementValue(r.payload.value)}}</view><view>审核后更新这一项，保留到访依据；不会自动认证整个地点；确认不允许办公或桌面不足会隐藏地点。</view><ActionButton v-if="r.payload.sourceUrl" class="underlink" @click="openMenu(r.payload.sourceUrl)">核对补充来源</ActionButton></view><view class="review-copy">{{r.payload.text}}</view><view v-if="r.note" class="meta">处理说明：{{r.note}}</view></view></view>
<view v-if="tab==='review'&&session.canReview" class="review-workspace"><view class="notice">审核直接在你的账号中完成。发布前核对来源与电脑办公门槛；隐藏、退回和恢复需写明依据。所有处理留存记录。</view><view class="row"><view class="section-title">地点投稿与隐藏记录</view><ActionButton class="underlink" :disabled="working==='import'" @click="importCandidates">导入公开地点线索</ActionButton></view><view v-if="!queue.places.length" class="empty-note">暂无待处理地点。</view><view v-for="p in queue.places" :key="p.id" class="contribution-card"><view class="row"><view class="card-name">{{p.name}}</view><text class="status-chip tone-unknown">{{statusLabels[p.reviewStatus]}}</text></view><view class="meta">{{p.contributor}} 贡献 · {{p.address}}</view><view class="review-facts"><text>{{p.laptopFriendly?'✓ 允许电脑':'电脑规则待确认'}}</text><text>{{p.deskFits?'✓ 电脑与鼠标可放下':'桌面待确认'}}</text><text>{{p.budget}}</text><text>{{p.location?'已提供 GCJ-02 坐标，审核时核对门店入口':'坐标待核对'}}</text></view><view v-if="p.publicationIssues?.length" class="notice"><view v-for="issue in p.publicationIssues" :key="issue">· {{issue}}</view></view><view class="chips"><ActionButton class="underlink" @click="openMenu(p.sourceUrl)">核对公开来源 <AppIcon name="arrow-up-right"/></ActionButton><ActionButton v-if="p.menuUrl" class="underlink" @click="openMenu(p.menuUrl)">查看菜单 <AppIcon name="arrow-up-right"/></ActionButton><ActionButton v-if="['pending','candidate'].includes(p.reviewStatus)" class="underlink" @click="contribute(p.id)">补充信息</ActionButton></view><view v-if="p.note" class="notice">{{p.note}}</view><textarea v-model="notes[p.id]" class="form-textarea short" placeholder="处理依据；退回 / 恢复时必填" maxlength="400"/><view class="review-actions"><template v-if="['pending','candidate'].includes(p.reviewStatus)"><ActionButton class="black-button" :disabled="working===p.id||!!p.publicationIssues?.length" @click="review('place',p.id,'approve')">确认来源并通过</ActionButton><ActionButton class="outline-button" :disabled="working===p.id" @click="review('place',p.id,p.reviewStatus==='candidate'?'hide':'reject')">{{p.reviewStatus==='candidate'?'隐藏地点':'退回补充'}}</ActionButton></template><ActionButton v-else-if="p.reviewStatus==='candidate'" class="outline-button" :disabled="working===p.id" @click="review('place',p.id,'hide')">隐藏地点</ActionButton><ActionButton v-else class="black-button" :disabled="working===p.id" @click="review('place',p.id,'restore')">核对后恢复展示</ActionButton></view></view>
<view class="section-title queue-heading">办公体验</view><view v-if="!queue.reviews.length" class="empty-note">暂无待审核体验。</view><view v-for="r in queue.reviews" :key="r.id" class="contribution-card"><view class="card-name">{{r.placeName}}</view><view class="meta">{{r.contributor}} · {{r.payload.date}} · {{r.payload.period}}</view><view v-if="r.payload.kind==='confirmation'" class="notice">到访核对：{{r.payload.confirmationFields.map((f:string)=>({laptopFriendly:'电脑许可',deskFits:'桌面条件',cost:'费用规则',hours:'开放时间'} as Record<string,string>)[f]).join('、')}}。通过后单独展示，不覆盖原始来源。</view><view v-if="r.payload.kind==='supplement'" class="notice"><view>补充 {{supplementLabels[r.payload.field]}}：{{supplementValue(r.payload.previous)}} → {{supplementValue(r.payload.value)}}</view><view>审核后更新这一项，保留到访依据；不会自动认证整个地点；确认不允许办公或桌面不足会隐藏地点。</view><ActionButton v-if="r.payload.sourceUrl" class="underlink" @click="openMenu(r.payload.sourceUrl)">核对补充来源</ActionButton></view><view class="review-copy">{{r.payload.text}}</view><textarea v-model="notes[r.id]" class="form-textarea short" placeholder="处理说明，退回时必填"/><view class="review-actions"><ActionButton class="black-button" :disabled="working===r.id" @click="review('review',r.id,'approve')">{{r.payload.kind==='supplement'?'通过并更新这一项':'通过体验'}}</ActionButton><ActionButton class="outline-button" :disabled="working===r.id" @click="review('review',r.id,'reject')">退回</ActionButton></view></view>
<view class="section-title queue-heading">地点纠错</view><view v-if="!queue.reports.length" class="empty-note">暂无未处理纠错。</view><view v-for="r in queue.reports" :key="r.id" class="contribution-card"><view class="card-name">{{r.placeName}} · {{r.payload.reason}}</view><view class="meta">{{r.payload.date}}</view><view class="review-copy">{{r.payload.detail}}</view><ActionButton v-if="r.payload.sourceUrl" class="underlink" @click="openMenu(r.payload.sourceUrl)">查看依据 <AppIcon name="arrow-up-right"/></ActionButton><textarea v-model="notes[r.id]" class="form-textarea short" placeholder="核对结果与处理依据"/><view class="review-actions"><ActionButton class="black-button" :disabled="working===r.id" @click="review('report',r.id,'resolve')">记录处理结果</ActionButton><ActionButton class="outline-button" :disabled="working===r.id" @click="review('place',r.placeId,'hide',notes[r.id])">核对后隐藏地点</ActionButton></view></view>
<view class="section-title queue-heading">最近处理记录</view><view v-for="(h,i) in queue.history" :key="i" class="audit-row"><text>{{new Date(h.at).toLocaleString()}}</text><text>{{actionLabels[h.action]||'信息更新'}} {{h.note}}</text></view></view>
</template></view></template>
